local DoctorioUI, E, L = unpack((select(2, ...)))

local _G = _G

-- Details profile
function DoctorioUI:Setup_Details()
	if not E:IsAddOnEnabled('Details') then return end

	local Details = _G.Details

	-- Profile name
	local name = 'Doctorio ' .. DoctorioUI.Version

	-- Profile string
	local retail = [[D!ProfileV2-]]

	Details:ImportProfile(retail, name)

	-- Apply the profile
	if Details:GetCurrentProfileName() ~= name then
		Details:ApplyProfile(name)
	end

	-- Load the profile on all characters
	Details.always_use_profile = true
	Details.always_use_profile_name = name

	DoctorioUI:Print(L["Details profile has been set."])
end
